from __future__ import annotations
from .research_header import inject_research_help


def memo_citation_check_page_html() -> str:
	html = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Memo Citation Check | AI CaseLibrary</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;600;700;800&display=swap" rel="stylesheet">
<style>
:root{--ink:#182421;--muted:#66756f;--paper:#e8eee9;--surface:#fbfdf9;--line:#cbd8d0;--teal:#087f73;--rust:#bd5638;--gold:#c18a25;--blue:#32639b}*{box-sizing:border-box}body{margin:0;color:var(--ink);font-family:Manrope,sans-serif;background:radial-gradient(circle at 80% 0,#d8e9e1 0,transparent 35%),linear-gradient(135deg,#eef3ed,#e5ece8);min-height:100vh}header{height:72px;padding:0 5vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);background:rgba(251,253,249,.84)}.brand{font-size:18px;font-weight:800;letter-spacing:.02em}.brand small{display:block;color:var(--muted);font-size:10px;font-weight:600;letter-spacing:.1em;text-transform:uppercase}.nav{display:flex;gap:8px}.nav a{padding:8px 10px;color:var(--muted);font-size:11px;text-decoration:none;border-radius:4px}.nav a:hover,.nav a.active{color:var(--ink);background:#dce9e2}.wrap{width:min(1200px,90vw);margin:0 auto;padding:58px 0 70px}.eyebrow{color:var(--rust);font:500 11px/1 "DM Mono",monospace;letter-spacing:.12em;text-transform:uppercase}h1{max-width:720px;margin:12px 0 10px;font-size:clamp(34px,5vw,64px);line-height:1.02;letter-spacing:-.04em}.lead{max-width:650px;color:var(--muted);font-size:15px;line-height:1.65}.upload{margin-top:34px;padding:28px;border:1px solid var(--line);background:rgba(251,253,249,.82);box-shadow:0 18px 50px rgba(24,36,33,.08)}.drop{display:grid;place-items:center;min-height:210px;padding:28px;border:1px dashed #8da89b;background:#f4f8f4;text-align:center;cursor:pointer}.drop:hover,.drop.drag{border-color:var(--teal);background:#eaf5f0}.drop strong{display:block;font-size:18px}.drop span{display:block;margin-top:8px;color:var(--muted);font-size:12px}.drop input{display:none}.actions{display:flex;align-items:center;gap:12px;margin-top:16px}.button{height:40px;padding:0 15px;border:0;border-radius:4px;background:var(--ink);color:white;font:700 12px Manrope;cursor:pointer}.button.secondary{border:1px solid var(--line);background:transparent;color:var(--ink)}.button:disabled{opacity:.45;cursor:wait}.status{color:var(--muted);font-size:12px}.notice{margin-top:16px;color:var(--muted);font-size:11px;line-height:1.5}.notice strong{color:var(--ink)}.error{margin-top:18px;padding:12px;border-left:3px solid var(--rust);background:#fff3ee;color:#87341f;font-size:12px}.hidden{display:none}.results{margin-top:42px}.result-head{display:flex;align-items:end;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line);padding-bottom:14px}.result-head h2{margin:0;font-size:22px}.meta{color:var(--muted);font-size:11px}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0}.metric{padding:14px;border:1px solid var(--line);background:rgba(251,253,249,.75);border-radius:4px}.metric strong{display:block;font-size:22px;margin-bottom:3px}.metric span{color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.08em;font-weight:600}.section{margin:30px 0}.section h3{font-size:16px;margin:16px 0 12px;border-bottom:1px solid var(--line);padding-bottom:8px}.authority{padding:12px;margin-bottom:8px;border:1px solid var(--line);border-radius:4px;background:#f8fbf8}.authority strong{display:block;font-size:12px;margin-bottom:3px}.authority-meta{color:var(--muted);font-size:10px;margin-bottom:6px}.authority-issues{margin:4px 0;font-size:10px}.issue-tag{display:inline-block;margin-right:6px;padding:2px 5px;background:#e1ebe5;border-radius:3px;color:#176659}.treatment-flag{display:inline-block;margin:6px 6px 0 0;padding:4px 7px;border-radius:3px;font:600 10px "DM Mono",monospace}.treatment-flag.positive{background:#e1f0e8;color:#186657}.treatment-flag.negative{background:#f6e6d6;color:#8c5519}.empty{color:var(--muted);font-size:12px;padding:12px;background:#f8fbf8;border-radius:4px}.related-item{padding:8px;margin-bottom:6px;border-left:2px solid var(--teal);background:rgba(8,127,115,.04);font-size:11px}.related-item-title{font-weight:600;color:var(--ink);margin-bottom:2px}@media(max-width:760px){.wrap{padding-top:40px}.summary{grid-template-columns:repeat(2,1fr)}.authority{padding:10px;font-size:14px}}
</style>
</head>
<body><header><div class="brand">ILIT <small>Memo citation check</small></div><nav class="nav"><a href="/data-explorer">Research</a><a href="/citation-map">Citation Map</a><a href="/live-analysis">Live Analysis</a><a class="active" href="/memo-citation-check">Memo Check</a></nav></header>
<main class="wrap"><div class="eyebrow">Citation analysis</div><h1>Check your draft for citation completeness.</h1><p class="lead">Upload a memo or brief (DOCX/PDF) to detect all cited authorities, identify treatment status, and discover commonly cited authorities on related issues that may strengthen your argument.</p>
<section class="upload"><label class="drop" id="drop"><input id="file" type="file" accept=".docx,.pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/pdf"><strong id="fileLabel">Choose a DOCX or text PDF</strong><span>Maximum 10 MB · no scanned-PDF OCR or permanent upload</span></label><div class="actions"><button class="button" id="analyze" disabled>Analyze document</button><button class="button secondary" id="clear" type="button">Clear</button><span class="status" id="status">No document selected</span></div><p class="notice"><strong>Privacy boundary:</strong> Upload is held in memory for this analysis only. No document is stored, logged, or sent to external services.</p><div class="error hidden" id="error"></div></section>
<section class="results hidden" id="results"><div class="result-head"><h2 id="resultTitle">Analysis</h2><div class="meta" id="resultMeta"></div></div><div class="summary" id="summary"></div><div class="section"><h3>Cited Authorities</h3><div id="cited"></div></div><div class="section"><h3>Authority Treatment</h3><div id="treatment"></div></div><div class="section"><h3>Missing Authorities</h3><p class="meta" style="margin-bottom:12px">Commonly cited on issues raised in your draft but not yet cited. These may strengthen your argument.</p><div id="missing"></div></div></section></main>
<script>
const fileInput=document.getElementById('file'),drop=document.getElementById('drop'),analyze=document.getElementById('analyze'),clear=document.getElementById('clear'),status=document.getElementById('status'),error=document.getElementById('error'),results=document.getElementById('results');let selected=null;
const esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function showError(message){error.textContent=message;error.classList.toggle('hidden',!message)}
function choose(file){selected=file||null;document.getElementById('fileLabel').textContent=selected?selected.name:'Choose a DOCX or text PDF';analyze.disabled=!selected;status.textContent=selected?`${(selected.size/1024/1024).toFixed(2)} MB selected`:'No document selected';showError('');}
function authorityRow(authority){const issuesTags=authority.issues?.map(i=>`<span class="issue-tag">${esc(i)}</span>`).join('') || '';const citingText=authority.citing_count>0?`${authority.citing_count} citing case${authority.citing_count!==1?'s':''}`:' not yet cited';return `<div class="authority"><strong>${esc(authority.title)}</strong><div class="authority-meta">${esc(authority.citation || authority.id)} · ${esc(authority.court)} · ${esc(authority.date || 'Date unknown')}</div>${issuesTags ? `<div class="authority-issues">${issuesTags}</div>` : ''}<div style="color:var(--muted);font-size:10px;margin-top:4px">${citingText}</div></div>`;}
function treatmentRow(citation){if(!citation.resolved_case_id){return `<div class="authority" style="opacity:.6"><strong>${esc(citation.reference_text)}</strong><div class="authority-meta">${esc(citation.kind)} · Unresolved</div></div>`;}const treatment=citation.treatment||{};const flags=treatment.treatment_flags || [];const hasTreatment=treatment.has_treatment;const treatmentHTML=hasTreatment?flags.map(f=>`<span class="treatment-flag ${f.includes('negative')?'negative':'positive'}">${esc(f.replace('_',' ').toUpperCase())}</span>`).join(''):' ';const related=citation.related_authorities||[];const relatedHTML=related.length>0?related.map(r=>`<div class="related-item"><div class="related-item-title">${esc(r.title)}</div><div style="color:var(--muted)">${esc(r.citation||'')} · ${esc(r.court)}</div></div>`).join(''):'';return `<div class="authority"><strong>${esc(citation.reference_text)}</strong><div class="authority-meta">${esc(citation.resolved_case_title||'unresolved')} · ${citation.resolved_case_citation?esc(citation.resolved_case_citation):''}</div>${hasTreatment ? `<div style="margin:6px 0">${treatmentHTML}</div>` : '<div style="color:var(--muted);font-size:11px;margin:6px 0">No treatment data</div>'}</div>`;}
function missingRow(authority){const reason=authority.reason || 'Commonly cited on same issues';return `<div class="authority"><strong>${esc(authority.title)}</strong><div class="authority-meta">${esc(authority.citation || authority.id)} · ${esc(authority.court)} · ${esc(authority.date || 'unknown')}</div><div style="color:var(--muted);font-size:10px;margin-top:4px;font-style:italic">${esc(reason)}</div></div>`;}
function render(data){document.getElementById('resultTitle').textContent=data.filename;document.getElementById('resultMeta').textContent=`${data.paragraph_count} paragraphs · ${data.text_length} characters`;const m=data.memo_analysis||{};document.getElementById('summary').innerHTML=`<div class="metric"><strong>${m.total_authorities_cited||0}</strong><span>Authorities cited</span></div><div class="metric"><strong>${m.resolved_authorities||0}</strong><span>Resolved in iLit</span></div><div class="metric"><strong>${m.authorities_with_treatment||0}</strong><span>With treatment data</span></div><div class="metric"><strong>${m.missing_authorities_found||0}</strong><span>Missing authorities</span></div>`;const cited=data.case_citations||[];const missing=data.missing_authorities||[];document.getElementById('cited').innerHTML=cited.length>0?cited.map(authorityRow).join(''):'<div class="empty">No case citations found in document.</div>';const treatedCitations=cited.filter(c=>c.resolved_case_id);document.getElementById('treatment').innerHTML=treatedCitations.length>0?treatedCitations.map(treatmentRow).join(''):'<div class="empty">Analyze document to see treatment status of cited authorities.</div>';document.getElementById('missing').innerHTML=missing.length>0?missing.map(missingRow).join(''):'<div class="empty">No commonly cited authorities found on same issues. Your citation coverage looks thorough.</div>';results.classList.remove('hidden');}
fileInput.onchange=()=>choose(fileInput.files[0]);['dragenter','dragover'].forEach(name=>drop.addEventListener(name,e=>{e.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(name=>drop.addEventListener(name,e=>{e.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>choose(e.dataTransfer.files[0]));analyze.onclick=async()=>{if(!selected)return;analyze.disabled=true;status.textContent='Analyzing document…';showError('');const body=new FormData();body.append('file',selected);try{const response=await fetch('/memo-citation-check',{method:'POST',body});const data=await response.json();if(!response.ok)throw new Error(data.detail||`Request failed (${response.status})`);render(data);status.textContent='Analysis complete';}catch(e){showError(e.message);status.textContent='Analysis failed';}finally{analyze.disabled=false}};clear.onclick=()=>{selected=null;fileInput.value='';choose(null);results.classList.add('hidden');};
</script></body></html>'''
	example = r'''
<script>
// A local text-PDF sample, never uploaded until Analyze document is selected.
function sampleMemoPdf(){
 const text='Synthetic sample - not a real memo or legal advice. Verify Canada (Minister of Citizenship and Immigration) v. Vavilov, 2019 SCC 65 against the authoritative decision.';
 const stream=`BT /F1 11 Tf 40 740 Td (${text.replace(/[\\()]/g,'\\$&')}) Tj ET`;
 const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`];
 let pdf='%PDF-1.4\n',offsets=[0];
 objects.forEach((object,index)=>{offsets.push(pdf.length);pdf+=`${index+1} 0 obj\n${object}\nendobj\n`});
 const start=pdf.length;
 pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`+offsets.slice(1).map(offset=>`${String(offset).padStart(10,'0')} 00000 n \n`).join('');
 pdf+=`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF\n`;
 return new File([pdf],'example-memo.pdf',{type:'application/pdf'});
}
const sampleButton=document.createElement('button');
sampleButton.type='button';sampleButton.className='button secondary';sampleButton.textContent='Load sample memo';
sampleButton.onclick=()=>{fileInput.value='';choose(sampleMemoPdf());results.classList.add('hidden');};
document.querySelector('.upload .actions').append(sampleButton);
const sampleNote=document.createElement('p');sampleNote.className='notice';
sampleNote.textContent='Synthetic sample: not a real memo or legal advice. It cites Vavilov (2019 SCC 65) for practice only. Loading it stays in this browser; select Analyze document to check its citation.';
document.querySelector('.upload').append(sampleNote);
if(new URLSearchParams(location.search).get('example')==='vavilov')sampleButton.click();
</script>'''
	return inject_research_help(html.replace('</body>', example + '</body>', 1))
